head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > adaptiveStyle]<br/>GridView 가 적응형 웹(Adaptive Web) 레이아웃일때 Column 에 적용될 CSS 속성을 설정합니다.",
    "validation" : [
        "GridView 가 적응형 웹(Adaptive Web) 레이아웃일때 Column 에 적용될 CSS 속성을 설정합니다.",
        "GridView 의 adaptive='crosstab' 이고 적응형 웹 레이아웃일때 적용됩니다.",
        "문자열 설정 시, Column 에 적용하려는 CSS 속성과 값을 설정합니다.",
        "문자열 설정 시, 'styleName1:styleValue1;styleName2:styleValue2;...' 포맷의 CSS 선언 리스트를 설정합니다.",
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    //  - adaptive=crosstab / adaptiveThreshold=2000(현재 브라우저 너비 이상) : 최초 로딩 시 적응형 레이아웃 상태
    //  - adaptiveStyle = CSS 선언 3개 (배경색 / 글자색 / 굵기)
    con_adaptive.setValue("crosstab");
    con_adaptiveThreshold.setValue("2000");
    con_adaptiveStyle.setSelectedIndex(2);

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - adaptiveStyle 은 @dynamic N 이므로 con 변경은 Target 재생성으로만 반영된다.
//  - Body 의 1번째 Column(col1) 에만 adaptiveStyle 을 설정하고, 2번째 Column(col2) 은 미설정 (비교용)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 설정 (GridView 속성은 createCList 로 빈값 자동 제외, Column 속성은 값이 있을 때만 추가)
    let cAdaptiveStyle = con_adaptiveStyle.getValue();
    let attrAdaptiveStyle = (cAdaptiveStyle === '') ? '' : ' adaptiveStyle="' + cAdaptiveStyle + '"';

    let properties = {
        adaptive          : con_adaptive.getValue(),
        adaptiveThreshold : con_adaptiveThreshold.getValue(),
        dataList          : "data:dlt_bind"
    };
    let cList = $c.gcm.createCList(properties);

    // 테스트 참고 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Body 의 col1 Column 에만 adaptiveStyle 설정, col2 는 미설정 (비교용)\n[절차] con 선택 -> Target 재생성 -> adaptiveStyle 확인\n[확인] 적응형 레이아웃 여부(브라우저 너비 <= adaptiveThreshold, 미설정 시 480) 에 따라 col1 셀 스타일 적용이 달라지는지 확인\n[참고] 브라우저 창 너비를 adaptiveThreshold 이하로 줄였다 늘리면 레이아웃이 즉시 전환되므로, 전환 후 다시 확인 버튼 클릭"', '', 'label1');

    // dataList 생성 (col1~col4 / 4행)
    await $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" id="" style="width:600px;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="adaptiveStyle 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col1" value=""' + attrAdaptiveStyle + '></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// Body Cell 의 computed style (배경색 / 글자색 / 굵기) 을 한 줄로 반환
scwin.getCellStyle = function (td) {
    if (!td) {
        return '(요소 없음)';
    }
    let cs = window.getComputedStyle(td);
    return "배경색 = " + cs.backgroundColor + " / 글자색 = " + cs.color + " / 굵기 = " + cs.fontWeight;
}



// adaptiveStyle 적용 확인
//  - validation 2 : 적응형 레이아웃 여부 (브라우저 너비 / 임계값 / w2grid_adaptive_crosstab 클래스)
//  - validation 1, 3, 4 : col1 Body Cell 의 computed style (CSS 선언 리스트의 각 속성 반영 여부)
scwin.btn_checkAdaptiveStyle_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");

    let cThreshold = target1.options.adaptiveThreshold;
    let strThreshold = (cThreshold === '' || cThreshold == null) ? '480(미설정)' : cThreshold;
    let bAdaptive = target1.render.className.split(/\s+/).indexOf("w2grid_adaptive_crosstab") > -1;

    // col1 Body Cell 전체 데이터 행의 computed style (행마다 같으면 한 번만 표시)
    let arrStyle = [];
    let nRow = dlt_bind.getRowCount();
    for (let i = 0; i < nRow; i++) {
        let td = document.querySelector("td[id$='target1_cell_" + i + "_0']");
        let strStyle = scwin.getCellStyle(td);
        if (arrStyle.indexOf(strStyle) === -1) {
            arrStyle.push(strStyle);
        }
    }

    bottom.setReturnValue("브라우저 너비 : " + window.innerWidth + "px, adaptive : " + (target1.options.adaptive || '(미설정)') + ", adaptiveThreshold : " + strThreshold + " -> 적응형 레이아웃 : " + bAdaptive);
    bottom.setReturnValue("Body col1 (" + nRow + "개 행) : " + arrStyle.join(" | "));
}
